import {ENTRY_DETAILS} from './entry-details.js';
export const VERSION='Anna-Prototyp 0.6 / Grammatik 0.5.0';
export const INITIAL={format:'tei',host:'uni-support',release:'private',experience:'unknown',event:null,access:'unknown',advice:'unknown',license:'unknown',sync:'unknown',backup:'unknown',publicationHost:'unknown',publicationService:'unknown'};
export const LABELS={publicationHost:{unknown:'Noch offen',same:'Eigenes Publikationsrepo auf gleichem Host',other:'Eigenes Publikationsrepo auf anderem Host'},format:{tei:'TEI mit vorbereiteter Unterstützung',markdown:'Markdown mit benannten semantischen Grenzen'},host:{'uni-support':'Uni-GitLab mit Beratung','uni-only':'Uni-GitLab als Hosting ohne Beratung',other:'Anderer geeigneter Dienst'},release:{private:'Interner Arbeitsstand',review:'Begrenzter Prüfausschnitt',public:'Öffentliche Teilpublikation'},experience:{unknown:'Ungeklärt',github:'GitHub bereits genutzt',gitlab:'GitLab bereits genutzt',none:'Noch keine Plattformpraxis'},event:{mira:'Mira liest einen Abschnitt gegen',teaching:'Ein Lehrtermin steht an',leaving:'Die institutionelle Anbindung endet',crash:'Der Arbeitsrechner ist ausgefallen'},availability:{unknown:'Ungeklärt',ends:'Endet / nicht mehr verfügbar',stays:'Bleibt nachweislich verfügbar'},proof:{unknown:'Ungeklärt',yes:'Ja, nachgewiesen',no:'Nein'}};
export const EVENT_COPY={
 mira:{title:'Mira hat eine Idee zu Annas schwieriger Passage.',text:'Anna schickt Mira einen klar bezeichneten Ausschnitt. Aus einer Rückfrage könnte eine bessere Deutung entstehen – wenn Kontext, Rückkanal und Integration gut vereinbart sind.',story:['Anna kennt die Passage inzwischen fast auswendig. Trotzdem ist sie unsicher, ob ihre Erklärung die Anspielung richtig trifft. Mira hat zu ähnlichen Texten gearbeitet und bietet an, den Abschnitt gegenzulesen. Anna freut sich: Ein zweites Paar Augen könnte genau jetzt helfen.','Aber was soll Mira bekommen? Ein vorbereiteter Ausschnitt mit den Editionsprinzipien reicht vielleicht schon. Soll Mira nur kommentieren oder Änderungen direkt vorschlagen? Git kann die Fassungen vergleichbar halten und einen gezielten Änderungsvorschlag aufnehmen.','Anna prüft Miras Hinweise und hält die fachlichen Gründe fest. Sie benennt den Beitrag ihrer Kollegin und plant Zeit für Rückfragen ein. Die technische Möglichkeit zur Zusammenarbeit wird so zu einer tatsächlich nutzbaren Unterstützung.'],task:'Prüfausschnitt und Rückkanal mit Mira vereinbaren; ihren Beitrag dokumentieren.',role:'Anna und Mira',ids:'P01-C01 · P01-R07 · P01-S02'},
 teaching:{title:'Dieses Semester wird die Edition zum Seminar.',text:'Anna möchte ihren Studierenden einen lebensnahen Einblick in die werdende Edition geben: lesen, diskutieren und eine offene editorische Frage gemeinsam prüfen.',story:['Anna wird in diesem Semester eine Lehrveranstaltung zu ihrem Text halten. Sie möchte zeigen, wie eine Edition entsteht: mit unsicheren Lesarten, Kommentaren im Entwurf und Entscheidungen, die noch einmal verändert werden können. Ein vorbereiteter Abschnitt wäre ein wunderbarer Ausgangspunkt.','Aber hat sie alles bedacht? Nicht jede interne Notiz ist für das Seminar bestimmt. Die Gruppe braucht eine verständliche Fassung mit klarem Qualitätsstatus. Anna kann einen geprüften Datenstand festhalten und daraus eine Lehrfassung erzeugen. Mit Git lässt sich später genau auf diesen Stand zurückkommen.','Wenn Studierende Vorschläge machen, kann Anna sie getrennt prüfen und begründet übernehmen. Die Seminarfassung bleibt nachvollziehbar, während die Edition weiterwächst. Ob der Ausschnitt auch öffentlich publiziert wird, entscheidet Anna gesondert.'],task:'Umfang, Lesekreis und Qualitätsstatus der Lehrfassung festlegen; Rechte und Schutzbedarf prüfen.',role:'Anna; bei Bedarf Lehr- und Infrastrukturunterstützung',ids:'P01-C03 · P01-R05 · P01-R07 · P01-S04'},
 leaving:{title:'Anna verlässt die Universität. Ihre Edition kommt mit.',text:'Das Projekt ist noch nicht abgeschlossen, und Anna möchte weiterarbeiten. Ihr Repo lässt sich an einen neuen Ort umziehen. Welche Zugänge enden tatsächlich – und was braucht sie für den Wechsel?',story:['Anna bekommt die Nachricht, dass ihr bisheriger Universitätszugang in einigen Monaten ausläuft. Sie hat noch viele Ideen für den Kommentar. Muss sie nun aufhören? Zum Glück sind ihre Dateien und die Git-Geschichte nicht nur auf dem Uni-Server gespeichert: Auch ihre vollständige lokale Kopie gehört zum Arbeitsweg.','Sie kann das Repo auf einen anderen geeigneten Dienst übertragen. Für ihre wenigen Textdateien und den einfachen Hauptbranch braucht sie vor allem eine gute Schritt-für-Schritt-Anleitung: abgleichen, neues privates Repo anlegen, Dateien samt Geschichte übertragen, frische Kopie testen und den neuen Arbeitsort dokumentieren.','Aber der Repo-Umzug ist nur eine der Fragen. Bleibt ihre bisherige Beratung erreichbar? Darf sie oXygen weiter nutzen? Funktioniert die Vorschau auch am neuen Ort? Anna klärt diese Bedingungen einzeln. Ein portabler Ausgabeweg und ihre Notizen helfen ihr, den Wechsel selbst zu bewältigen; bei Sonderfällen kann sie gezielt nachfragen.'],task:'Zugänge einzeln klären; Repo nach Anleitung vor Fristende umziehen, frische Kopie prüfen und neuen Arbeitsort dokumentieren.',role:'Anna; zuständige Stellen klären Konten und Berechtigung, direkte Hilfe bei Sonderfällen',ids:'P01-R02 · P01-R03 · P01-R04 · P01-L01 · P01-X01/X02'},
 crash:{title:'Der Laptop bleibt dunkel. Die Edition muss nicht verloren sein.',text:'Anna hat ihre Arbeit regelmäßig committet und auf das Uni-GitLab übertragen – so kann Git helfen, aus einem Defekt eine überschaubare Unterbrechung zu machen. Welche Stände hat sie tatsächlich gesichert?',story:['Anna möchte morgens am Kommentar weiterarbeiten, doch ihr Rechner startet nicht mehr. Der erste Gedanke ist erschreckend: die ganze Editionsarbeit! Dann erinnert sie sich an ihren Arbeitsweg. Was sie regelmäßig als Commit festgehalten und zum Uni-GitLab gepusht hat, liegt dort weiterhin samt Git-Geschichte.','Auf einem Ersatzrechner kann sie eine neue Kopie klonen und an diesem Stand weiterarbeiten. Genau hier liegt der praktische Wert ihrer Sicherungsstrategie aus Git und verlässlich betriebenem Uni-GitLab. Eine größere Katastrophe lässt sich so vermeiden.','Aber Git muss vernünftig genutzt werden: Nicht übertragene Änderungen sind nicht auf dem Server. Abbildungen oder andere Dateien außerhalb des Repos benötigen eine passende Sicherung. Anna prüft deshalb, welchen Stand sie wiederherstellen kann, testet Validierung und Vorschau und dokumentiert den Rückweg. Eine zusätzliche unabhängige Sicherung verbessert den Schutz.'],task:'Letzten übertragenen Stand neu klonen; weitere gesicherte Dateien ergänzen, Vorschau prüfen und Wiederherstellung dokumentieren.',role:'Anna mit einer verständlichen Wiederherstellungsanleitung; Hilfe nur soweit nötig',ids:'P01-R01 · P01-M04'}
};

function item(id,title,type,p,w,reason,action,role='Anna mit geeigneter Unterstützung'){return {id,title,type,p,w,reason,action,role};}
export function evaluate(s){
 const entries=[
 item('P01-C01','Unterstützung','c','mittel','mittel','Passende Expertise ist denkbar; eine Zusage und ein fachlicher Gewinn sind zunächst offen.','Einen kleinen verständlichen Reviewausschnitt und einen Rückkanal vorbereiten.','Anna und mögliche Mitwirkende'),
 item('P01-C02','Revision','c','mittel','hoch','Neue Erkenntnisse sind plausibel; Korrekturen betreffen zentrale Editionsziele. Ein gepflegter Ausgabeweg ist Voraussetzung.','Editionsprinzipien, Versionszuordnung und Ausgabeweg pflegen.'),
 item('P01-C03','Lehre','c','mittel','mittel','Anna interessiert sich für Lehre; ein konkreter Termin ist zunächst offen.','Geprüften Lehrstand und geeigneten Lesekreis vorbereiten.'),
 item('P01-C04','Teilpublikation','c','mittel','mittel','Ein fertiger Teilbestand kann bereits nutzbar sein; Umfang und Nachfrage bleiben offen.','Teilbestand fachlich abgrenzen, Qualitätsstatus und Zitation dokumentieren.'),
 item('P01-C08','Buchpublikation','c','ungeklärt','hoch','Ein Verlag könnte Lektorat, Gestaltung und passende Verbreitung ermöglichen. Eine Anfrage ist nicht vorausgesetzt; Rechte, Kosten und das Verhältnis zur offenen Datenfassung sind zu klären.','Buch- und Datenveröffentlichung sowie spätere Revisionen mit dem Verlag abstimmen.','Anna und interessierter Verlag; Rechte-/Vertragsberatung bei Bedarf'),
 item('P01-R01','Rechnerausfall','r','mittel','hoch','Git und Uni-GitLab können die übertragenen Editionsdateien samt Geschichte gegen Rechnerverlust absichern. Gefährdet bleiben nicht übertragene Änderungen und ungesicherte externe Dateien; Annas tatsächliche Routine ist noch ungeklärt.','Regelmäßig committen und pushen; neue Kopie ausprobieren, Sicherungsumfang dokumentieren und externe Dateien zusätzlich sichern.'),
 item('P01-R02','Repo-Zugang','r','ungeklärt','hoch','Die längerfristige Kontoregel ist noch nicht geklärt.','Zugang klären; Repo nach Anleitung umziehen und in einer frischen Kopie prüfen. Plattformfunktionen gesondert behandeln.'),
 item('P01-R03','Beratung','r','ungeklärt','mittel','Dauer und Alternativen der institutionellen Unterstützung sind noch offen.','Beratungsweg und verständliche Betriebsdokumentation vereinbaren.'),
 item('P01-R04','Werkzeugwechsel','r','ungeklärt','mittel','Die längerfristige Werkzeugberechtigung ist noch nicht geprüft. TEI-Dateien bleiben grundsätzlich bearbeitbar.','Werkzeugberechtigung klären und einen alternativen Arbeitsweg testen.'),
 item('P01-R05','Vertraulichkeit','r','mittel','hoch','Ungeprüfte Exporte oder Historien könnten interne Inhalte offenlegen; die Verteilung ist schwer zurückholbar.','Vor Commit sensible Inhalte abgrenzen; vor Freigabe Export und erreichbare Historie prüfen.'),
 item('P01-R06','Fortführung','r','ungeklärt','hoch','Ein Ausfall wird nicht unterstellt. Die Konzentration von Wissen und Verantwortung könnte die Fortführung erschweren.','Zustimmende Vertretung, Richtlinien und Übergabepaket mit Probelauf vereinbaren.'),
 item('P01-R07','Zusatzaufwand','r','mittel','mittel','Beiträge und Teilfreigaben schaffen Rückfragen und zusätzliche Prüfaufgaben. Umfang ist noch offen.','Auftrag, Freigabeumfang und Rückmeldekanal begrenzen.'),
 item('P01-R08','Hostwechsel','r','ungeklärt','hoch','Die Portabilität der noch einzurichtenden Vorschau und Ausgabe ist nicht nachgewiesen.','Lokale Ausgabe außerhalb der Hosting-Automation testen.')
 ];
 const get=id=>entries.find(e=>e.id===id);
 if(s.host==='other'){get('P01-R02').reason='Der Arbeitsort ist kein Uni-GitLab. Institutionell unabhängige Kontokontrolle und Vertretung sind trotzdem noch nicht nachgewiesen; der Eintrag bleibt bis zur Klärung offen.';get('P01-R03').reason='Unterstützung am anderen Dienst ist gesondert zu vereinbaren. Die Plattformwahl schafft selbst keine Editionsberatung.';}
 if(s.host==='uni-only'){get('P01-R03').status='Unterstützungsbedarf';get('P01-R03').reason='Im gewählten Angebot gibt es bereits keine Editionsberatung. Es geht um eine aktuelle Versorgungslücke, nicht um die Wahrscheinlichkeit ihres späteren Wegfalls.';}
 if(s.format==='markdown'){get('P01-R04').status='nicht anwendbar';get('P01-R04').reason='Dieses Szenario setzt keine oXygen-/TEI-Arbeitsumgebung voraus. Andere Werkzeug- und Zugangsfragen sind weiterhin zu klären.';}
 if(s.release==='review'){get('P01-R05').reason='Ein begrenzter Prüfausschnitt ist vorgesehen. Sein Inhalt und Empfängerkreis werden geprüft; die Arbeitsgeschichte wird nicht automatisch mitgeteilt.';}
 if(s.release==='public'){get('P01-C04').reason='Eine öffentliche Teilpublikation ist beabsichtigt. Sie ist noch nicht als veröffentlicht oder tatsächlich genutzt nachgewiesen.';get('P01-R05').reason='Eine öffentliche Teilfreigabe ist vorgesehen: Inhalt, Rechte, Schutzbedarf und erreichbare Publikationshistorie benötigen eine konkrete Prüfung. Die Auswahl selbst beweist keine höhere Eintrittswahrscheinlichkeit.';}
 const before=entries.map(e=>({...e}));
 if(s.event==='mira'){Object.assign(get('P01-C01'),{p:'hoch',reason:'Mira hat für diesen Abschnitt zugesagt. Die Mitwirkung ist konkret, der fachliche Gewinn muss sich erst zeigen.'});Object.assign(get('P01-R07'),{p:'hoch',reason:'Der vereinbarte Review erfordert konkret Einführung, Rückfragen und Integration. Der Umfang bleibt begrenzt.'});}
 if(s.event==='teaching'){Object.assign(get('P01-C03'),{p:'hoch',reason:'Ein konkreter Lehrtermin macht die Nutzung eines geeigneten Ausschnitts absehbar; Freigabe und Vorbereitung bleiben nötig.'});Object.assign(get('P01-R07'),{p:'hoch',reason:'Die Lehrfassung benötigt konkret Zeit für Vorbereitung, Prüfung und Rückfragen.'});get('P01-R05').reason='Vor der Lehrfreigabe müssen Ausschnitt und erreichbare Begleitdaten geprüft werden. Ein Lehrtermin verlangt keine Freigabe der gesamten Arbeitsgeschichte.';}
 if(s.event==='leaving'){
  const conditions=[['P01-R02','access','Repo-Zugang'],['P01-R03','advice','Beratung'],['P01-R04','license','Werkzeugzugang']];
  for(const [id,key,name] of conditions){const e=get(id);if(e.status==='nicht anwendbar'||(id==='P01-R03'&&s.host==='uni-only'))continue;
   if(s[key]==='ends')Object.assign(e,{p:'hoch',reason:`Das Ende des bisherigen Zugangs zu ${name} ist im Testfall bestätigt. Eine Unterbrechung ist ohne geklärten Ersatz konkret absehbar.`});
   if(s[key]==='stays')Object.assign(e,{status:'im Testfall geklärt',reason:`${name} bleibt nachweislich verfügbar. Diese Folge des Institutionsereignisses entfällt im gewählten Testfall; andere Risiken bleiben bestehen.`});
   if(s[key]==='unknown')e.reason=`Die Uni-Anbindung endet, aber die Folge für ${name} ist ungeklärt. Das Ereignis allein setzt den Zugang nicht auf „endet“.`;
  }
  if(s.advice==='ends'){get('P01-R08').reason='Ein einfacher Repo-Umzug ist mit Anleitung auch ohne direkte Beratung möglich. Sonderfunktionen und die Portabilität des Ausgabewegs bleiben getrennt zu prüfen.';get('P01-C02').reason='Revisionspotenzial bleibt erhalten. Bei entfallender Unterstützung ist sein praktischer Zugang gefährdet, bis der Ausgabeweg erprobt wurde.';}
 }
 if(s.event==='crash'){
  const e=get('P01-R01');e.status='eingetreten';e.p='eingetreten';
  if(s.sync==='yes'&&s.backup==='yes')e.reason='Extern abgeglichener Repo-Stand und geprüfte unabhängige Sicherung liegen vor. Wiederherstellung ist vorzubereiten; Änderungen nach diesen Ständen können fehlen. Umfang und Aktualität bleiben zu kontrollieren.';
  else if(s.sync==='yes')e.reason='Der letzte übertragene Git-Stand bleibt trotz Rechnerausfall verfügbar: Anna kann ihn samt Geschichte neu klonen. Nicht übertragene Änderungen und externe Dateien brauchen gesonderte Prüfung; die zusätzliche unabhängige Sicherung ist '+(s.backup==='no'?'nicht vorhanden.':'ungeklärt.');
  else if(s.backup==='yes')e.reason='Eine geprüfte unabhängige Sicherung liegt vor. Ihre Aktualität entscheidet, welche Arbeit wiederherstellbar ist. Ein externer Git-Abgleich ist '+(s.sync==='no'?'nicht vorhanden.':'ungeklärt.');
  else if(s.sync==='no'&&s.backup==='no')e.reason='Im Testfall gibt es weder externen Abgleich noch unabhängige Sicherung. Wiederherstellbarkeit ist nicht nachgewiesen; verbleibende lokale Rettungsmöglichkeiten benötigen technische Prüfung.';
  else e.reason='Defekt eingetreten; verfügbare Stände sind nicht ausreichend geklärt. Zuerst externen Abgleich und Sicherung inventarisieren. Ungeklärt bedeutet weder sicher verloren noch wiederherstellbar.';
 }
 if(s.event==='leaving'&&s.publicationService==='ends')get('P01-R08').reason='Der bisherige institutionelle Publikationsdienst endet im Testfall. Anna muss Webhosting und Ausgabeweg prüfen und gegebenenfalls wechseln. Ein Repo-Umzug allein richtet keine neue Website ein.';
 const changes=entries.flatMap(e=>{const b=before.find(x=>x.id===e.id);return JSON.stringify(b)!==JSON.stringify(e)?[{before:b,after:e}]:[];});
 const formatText=s.format==='tei'?'TEI ist fachlich bevorzugt. Vorbereitete oXygen-Author-Umgebung, schlankes Schema, Git-Anbindung und Beratung sind einzurichten. Diese Auswahl bestätigt noch keine vorhandene Lizenz.':'Markdown senkt nicht automatisch den Aufwand. Eigene Konventionen, stabile IDs, Link-/Metadatenprüfungen und lokale Vorschau sind nötig. Eine TEI-vergleichbare editorische Semantik wird nicht behauptet.';
 const hostText=s.host==='uni-support'?'Das angenommene Angebot umfasst Hosting und Beratung. Konkrete Leistungen, Vertretung und Zugang nach Ausscheiden sind zu bestätigen.':s.host==='uni-only'?'Der Server stellt einen Arbeitsort bereit. TEI-Einrichtung, Vorschau und Beratung benötigen zusätzlich eine verantwortliche Stelle.':'Konto, Verfügungsrechte, Unterstützung und Export separat klären. Ein persönlicher Account, eine Organisation und wissenschaftliche Autorschaft sind unterschiedliche Fragen.';
 const releaseText=s.release==='private'?'Zunächst bleibt die Arbeit intern. Ein späterer kontrollierter Export ist vorzubereiten; die private Historie wird nicht automatisch öffentlich.':s.release==='review'?'Ein geprüfter Ausschnitt geht an einen benannten Lesekreis. Rückkanal, Zugriff und Anerkennung werden vereinbart; ein Branch allein begrenzt den Lesekreis nicht.':'Ein abgegrenzter Stand erhält fachliche Freigabe, Metadaten, Editionsprinzipien und geklärte Nutzungsbedingungen. Archivdienst und persistente Kennung werden gesondert vereinbart.';
 const experienceText=s.experience==='unknown'?'Plattformpraxis ist ungeklärt. Daraus wird kein Aufwandvorteil abgeleitet.':s.experience==='none'?'Eine kurze Einführung in Oberfläche, Commit und Abgleich ist einzuplanen.':`${s.experience==='github'?'GitHub':'GitLab'}-Erfahrung kann die Bedienung erleichtern. Sie entscheidet weder über das Arbeitsformat noch über die Publikations- oder Archivverantwortung.`;
 for(const entry of entries)Object.assign(entry,ENTRY_DETAILS[entry.id]);
 return {entries,before,changes,formatText,hostText,releaseText,experienceText};
}
export function rating(e){return e.status||`${e.p} / ${e.w}`;}
export function snapshot(s,result=evaluate(s)){
 return `${VERSION}\nStand: 20. Oktober 2026 · Fiktive Modellannahmen\nHorizont: fünf Jahre; qualitative Einschätzungen, keine Anbieterberatung.\n\nENTSCHEIDUNGEN\nArbeitsformat: ${LABELS.format[s.format]}\nUmgebung: ${LABELS.host[s.host]}\nFreigabe: ${LABELS.release[s.release]}\nPraxis: ${LABELS.experience[s.experience]}\nPublikationsort: ${LABELS.publicationHost[s.publicationHost]}\nEreignis: ${s.event?LABELS.event[s.event]:'Keines'}\n${s.event==='leaving'?`Repo-Zugang: ${LABELS.availability[s.access]}\nBeratung: ${LABELS.availability[s.advice]}\nWerkzeug: ${LABELS.availability[s.license]}\nPublikationsdienst: ${LABELS.availability[s.publicationService]}\n`:''}${s.event==='crash'?`Abgleich: ${LABELS.proof[s.sync]}\nSicherung geprüft: ${LABELS.proof[s.backup]}\n`:''}\nBEGRÜNDUNGEN\n${result.formatText}\n${result.hostText}\n${result.releaseText}\n${result.experienceText}\n\nCHANCEN UND RISIKEN (Plausibilität / Wirkung)\n${result.entries.map(e=>`${e.id} ${e.title}: ${rating(e)}${e.status?`; Wirkung ${e.w}`:''}\n${e.description}\n\nWarum diese Einschätzung: ${e.reason}\n\nWie hilft Git: ${e.git}\n\nWas gibt es zu bedenken: ${e.consider}\n\nHandlung: ${e.action}\nZuständig: ${e.role}`).join('\n\n')}\n\nEREIGNISAUFGABE\n${s.event?EVENT_COPY[s.event].task+' Zuständig: '+EVENT_COPY[s.event].role:'Kein Ereignis aktiv. Als nächstes Einrichtung, Sicherung und Beratung klären.'}\n\nOFFENE PUNKTE\nKonkrete Dienstbedingungen, Rechte, Werkzeugberechtigung, Finanzierung, Vertretung und langfristiger Archivträger. Sicherung, Migration und Übergabe sind geplant; ihre Umsetzung ist gesondert nachzuweisen.\n`;
}
